    }

    #[test]
    fn parses_workflow_with_overrides() {
        let yaml = r#"
workflows:
  onboarding:
    steps: [deps, database, seeds]
    overrides:
      seeds:
        required: true
        skip_prompt: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let workflow = &config.workflows["onboarding"];
        let override_ = &workflow.overrides["seeds"];
