    }

    #[test]
    fn rejects_unknown_workflow_field() {
        let yaml = r#"
workflows:
  default:
    stpes: [test]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field 'stpes' should be rejected");
    }

    #[test]
    fn rejects_unknown_step_override_field() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    overrides:
      test:
        requred: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown override field 'requred' should be rejected");
