        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.vars.len(), 2);
        assert!(matches!(
            config.vars.get("app_name"),
            Some(VarDefinition::Static(_))
        ));
        assert!(matches!(
            config.vars.get("version"),
            Some(VarDefinition::Computed { .. })
        ));
    }

    #[test]
    fn empty_vars_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.vars.is_empty());
    }

    #[test]
    fn serialize_omits_empty_vars() {
        let config: BivvyConfig = serde_yaml::from_str("app_name: test").unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(!yaml.contains("vars"), "empty vars should be omitted");
    }

    // --- Precondition parsing tests ---

    #[test]
    fn parses_precondition_command_succeeds() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: command_succeeds
      command: "test $(git branch --show-current) = main"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    // --- Unknown field rejection tests ---

    #[test]
    fn rejects_unknown_top_level_field() {
        let yaml = r#"
app_name: "TestApp"
steeps:
  test:
    command: "echo test"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown top-level field 'steeps' should be rejected");
        let err = result.unwrap_err().to_string();
        assert!(err.contains("unknown field"), "error should mention unknown field: {}", err);
    }

    #[test]
    fn rejects_unknown_settings_field() {
        let yaml = r#"
settings:
  max_parrallel: 8
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown settings field 'max_parrallel' should be rejected");
    }

    #[test]
    fn rejects_unknown_step_field() {
        let yaml = r#"
steps:
  test:
    commnad: "echo test"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step field 'commnad' should be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_field() {
        let yaml = r#"
workflows:
  default:
    stpes: [test]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field 'stpes' should be rejected");
    }

    #[test]
    fn rejects_unknown_step_override_field() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    overrides:
      test:
        requred: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown override field 'requred' should be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_settings_field() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    settings:
      non_interctive: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow settings field should be rejected");
    }

    #[test]
    fn rejects_unknown_environment_config_field() {
        let yaml = r#"
settings:
  environments:
    ci:
      detct:
        - env: CI
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown environment config field 'detct' should be rejected");
    }

    #[test]
    fn rejects_unknown_step_environment_override_field() {
        let yaml = r#"
steps:
  test:
    command: "echo test"
    environments:
      ci:
        commnad: "echo ci"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step env override field 'commnad' should be rejected");
    }

    #[test]
    fn valid_fields_still_parse_with_deny_unknown() {
        let yaml = r#"
app_name: "TestApp"
settings:
  default_output: quiet
  max_parallel: 8
steps:
  test:
    command: "echo test"
    depends_on: [other]
  other:
    command: "echo other"
workflows:
  default:
    steps: [other, test]
    overrides:
      test:
        required: true
    settings:
      non_interactive: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.app_name, Some("TestApp".to_string()));
        assert_eq!(config.settings.max_parallel, 8);
        assert!(config.steps.contains_key("test"));
    }
}

